    def _on_mining_preset_changed(self, *args):
        """Fill gradient mining controls from the selected preset."""
        name = self._mining_preset_var.get()
        preset = self._mining_presets.get(name)
        if not preset:
            return
        for key, entry_key in [("snr", "GRADIENT_MINING_THRESHOLD"),
                                ("ortho", "GRADIENT_MINING_ORTHO")]:
            entry = self.entries.get(entry_key)
            if entry and key in preset:
                entry.delete(0, tk.END)
                entry.insert(0, preset[key])

    def _on_training_preset_changed(self, *args):
        """Auto-fill MIN/MAX_TIMESTEP and show/hide custom block picker based on training preset."""
        preset = self.training_preset_var.get()

        # Show/hide custom block panel
        if preset == "Custom":
            self._training_custom_frame.grid()
        else:
            self._training_custom_frame.grid_remove()

        # Skip timestep auto-fill for Custom (user-driven)
        if preset == "Custom":
            self._last_area_applied = preset
            return

        # Only rewrite MIN/MAX when the Model Area actually CHANGED. This handler is also
        # invoked as a visibility refresh (arch switches, tab builds) — unconditionally
        # auto-filling wiped the user's hand-set timesteps on every one of those calls.
        if getattr(self, "_last_area_applied", None) == preset:
            return
        self._last_area_applied = preset

        # Auto-fill MIN/MAX_TIMESTEP entries
        min_entry = self.entries.get("MIN_TIMESTEP")
        max_entry = self.entries.get("MAX_TIMESTEP")
        if min_entry is None or max_entry is None:
            return

        if preset == "Style":
            min_val, max_val = "0", "400"
        else:  # Full Model, Identity, Style+Composition, Details
            min_val, max_val = "", ""

        min_entry.delete(0, tk.END)
        if min_val:
            min_entry.insert(0, min_val)
        max_entry.delete(0, tk.END)
        if max_val:
            max_entry.insert(0, max_val)
        self.settings["MIN_TIMESTEP"] = min_val
        self.settings["MAX_TIMESTEP"] = max_val
        if hasattr(self, "_update_noise_range_label"):
            try:
                self._update_noise_range_label()
            except Exception:
                pass

    def _set_all_training_blocks(self, value: bool):
        """Tick/untick all per-block checkboxes in Custom training mode."""
        for var in self.training_block_vars.values():
            var.set(value)

    def _set_category_training_blocks(self, category: str):
        """Select all blocks in a category (identity/style_composition/details). Clears others."""
        for key, var in self.training_block_vars.items():
            var.set(False)
        if category == "style_composition":
            for i in range(8):
                self.training_block_vars[f"double_blocks.{i}"].set(True)
            for i in (0, 1):
                self.training_block_vars[f"single_blocks.{i}"].set(True)
        elif category == "identity":
            for i in range(1, 17):
                self.training_block_vars[f"single_blocks.{i}"].set(True)
        elif category == "details":
            for i in range(12, 24):
                self.training_block_vars[f"single_blocks.{i}"].set(True)

    def _build_custom_training_patterns(self):
        """Build a list of include_patterns regexes from the Custom block checkboxes."""
        selected = [key for key, var in self.training_block_vars.items() if var.get()]
        if not selected:
            return None
        patterns = []
        for key in selected:
            # key is "double_blocks.N" or "single_blocks.N"
            kind, idx = key.split(".")
            patterns.append(rf".*{kind}\.{idx}\..*")
        return patterns

    def _on_extract_preset_changed(self, *args):
        """Show/hide custom block checkboxes and auto-switch timesteps/samples based on preset."""
        preset = self.extract_preset_var.get()
        if preset == "Custom":
            # Pack before Options so the custom card appears between Preset and Options.
            self._extract_custom_frame.pack(fill=tk.X, padx=36, pady=(0, 16),
                                             before=self._extract_options_anchor)
        else:
            self._extract_custom_frame.pack_forget()

        # Fast * presets force samples=0 (pure weight SVD)
        is_fast = preset in ("Fast SVD", "Fast Identity", "Fast Style+Composition", "Fast Details")
        if is_fast:
            self.extract_samples_var.set("0")
        elif preset in ("All Blocks", "Identity", "Style", "Style+Composition", "Details"):
            # Activation-weighted presets need samples>0; bump off 0 if user is coming from a Fast variant
            if self.extract_samples_var.get() == "0":
                self.extract_samples_var.set("16")

        # Timestep auto-fill
        if preset == "Style":
            self.extract_timesteps_var.set("late")
        elif preset in ("All Blocks", "Fast SVD", "Identity", "Fast Identity",
                        "Style+Composition", "Fast Style+Composition", "Details", "Fast Details"):
            self.extract_timesteps_var.set("all")

        # Reflect timestep combo state (samples may have just changed above)
        self._apply_extract_samples_state()

        # Update suggested output filename to match new preset
        self._update_extract_output_name()

    def _on_extract_samples_changed(self, *args):
        """Grey out timesteps when samples=0; map presets to their Fast variant where applicable."""
        if self.extract_samples_var.get() == "0":
            preset = self.extract_preset_var.get()
            # Map activation-weighted presets to their Fast equivalent so the UI reflects reality
            fast_map = {
                "All Blocks": "Fast SVD",
                "Identity": "Fast Identity",
                "Style": "Fast Style+Composition",   # Style is inherently timestep-based; Fast loses that meaning
                "Style+Composition": "Fast Style+Composition",
                "Details": "Fast Details",
            }
            if preset in fast_map:
                self.extract_preset_var.set(fast_map[preset])
                self.extract_timesteps_var.set("all")
        self._apply_extract_samples_state()

    def _apply_extract_samples_state(self):
        """Timesteps dropdown is meaningful only when forward passes > 0."""
        if self.extract_samples_var.get() == "0":
            self._extract_timesteps_combo.configure(state="disabled")
        else:
            self._extract_timesteps_combo.configure(state="readonly")

    def _set_all_extract_blocks(self, value: bool):
        """Tick/untick all per-block checkboxes in Custom mode."""
        for var in self.extract_block_vars.values():
            var.set(value)

    def _set_category_extract_blocks(self, category: str):
        """Select all blocks in a category (identity/style_composition/details). Clears others."""
        for key, var in self.extract_block_vars.items():
            var.set(False)
        if category == "style_composition":
            # double 0-7 + single 0-1 + single 2 (at full strength in Custom mode)
            for i in range(8):
                self.extract_block_vars[f"double_blocks.{i}"].set(True)
            for i in (0, 1, 2):
                self.extract_block_vars[f"single_blocks.{i}"].set(True)
        elif category == "identity":
            for i in range(1, 17):
                self.extract_block_vars[f"single_blocks.{i}"].set(True)
        elif category == "details":
            for i in range(12, 24):
                self.extract_block_vars[f"single_blocks.{i}"].set(True)

    def _update_extract_output_name(self):
        """Regenerate the suggested output filename from source + preset + rank."""
        source = self.extract_source_var.get().strip()
        if not source:
            return
        base = os.path.splitext(os.path.basename(source))[0]
        preset_slug = self.extract_preset_var.get().lower().replace("+", "_").replace(" ", "_")
        self.extract_output_var.set(f"{base}_{preset_slug}_r{self.extract_rank_var.get()}.safetensors")

    def _browse_extract_source(self):
        filepath = filedialog.askopenfilename(
            title="Select source LoRA",
            filetypes=[("SafeTensors", "*.safetensors"), ("All files", "*.*")],
            initialdir=self._lora_initialdir(),
        )
        if filepath:
            self.extract_source_var.set(filepath)
            self._update_extract_output_name()

    def _extract_log(self, text):
        """Append to extract log (preserves user scroll position). Marshals to the main
        thread — the extract worker calls this from its own thread."""
        import threading
        if threading.current_thread() is not threading.main_thread():
            self.master.after(0, self._extract_log, text)
            return
        self._append_global_log(text)
        self._smart_text_insert(self.extract_log, text)

    def _open_extract_folder(self):
        if self._extract_output_path and os.path.exists(self._extract_output_path):
            folder = os.path.dirname(self._extract_output_path)
            self._open_in_file_manager(folder)

    def _run_extract(self):
        """Start extraction in a background thread."""
        if str(self.extract_family_var.get()) == "krea2":
            self._run_extract_krea2()
            return

        source = self.extract_source_var.get()
        if not source or not os.path.exists(source):
            messagebox.showerror("Error", "Please select a valid source LoRA.")
            return

        output_name = self.extract_output_var.get().strip()
        if not output_name:
            messagebox.showerror("Error", "Please enter an output name.")
            return
        if not output_name.endswith(".safetensors"):
            output_name += ".safetensors"

        # Fast (weight-only, samples=0) presets run entirely from the safetensors file:
        # no pipeline is loaded, so don't demand a DiT/VAE/TE or a prompt they never use
        # (the CLI already worked without them).
        try:
            _samples = int(self.extract_samples_var.get().strip() or 0)
        except (ValueError, AttributeError):
            _samples = 0

        prompt = self.extract_prompt_var.get().strip()
        dit_path = self.prefs_vars["distilled_dit"].get()
        vae_path = self.prefs_vars["vae"].get()
        te_path = self.prefs_vars["text_encoder"].get()

        if _samples > 0:
            if not prompt:
                messagebox.showerror("Error", "Please enter a prompt (trigger word recommended).")
                return
            for path, name in [(dit_path, "DiT"), (vae_path, "VAE"), (te_path, "Text Encoder")]:
                if not path or not os.path.exists(path):
                    messagebox.showerror("Error", f"{name} not found:\n{path}\n\nCheck Preferences tab.")
                    return

        # Build block list from preset (or custom individual blocks)
        preset = self.extract_preset_var.get()
        custom_blocks = None  # Per-block list for Custom mode
        if preset in ("Identity", "Fast Identity"):
            blocks = ["identity"]
        elif preset in ("Style", "Style+Composition", "Fast Style+Composition"):
            blocks = ["style_composition"]
        elif preset in ("Details", "Fast Details"):
            blocks = ["details"]
        elif preset in ("All Blocks", "Fast SVD"):
            blocks = ["all"]
        else:  # Custom
            selected = [key for key, var in self.extract_block_vars.items() if var.get()]
            if not selected:
                messagebox.showerror("Error", "Custom mode: please select at least one block.")
                return
            blocks = ["custom"]
            custom_blocks = selected

        output_dir = self.prefs_vars["lora_output_dir"].get()
        os.makedirs(output_dir, exist_ok=True)
        output_path = os.path.join(output_dir, output_name)
        # Never silently overwrite: the name is built from source+preset+rank only, so two
        # different Custom selections at the same rank land on the same filename.
        if os.path.exists(output_path):
            _stem, _ext = os.path.splitext(output_path)
            _n = 2
            while os.path.exists(f"{_stem}_{_n}{_ext}"):
                _n += 1
            output_path = f"{_stem}_{_n}{_ext}"

        # Disable button, clear log
        self.extract_run_btn.configure(state="disabled")
        self.extract_open_btn.configure(state="disabled")
        self.extract_log.configure(state="normal")
        self.extract_log.delete(1.0, tk.END)
        self.extract_log.configure(state="disabled")
        self.extract_progress_var.set("Loading models...")

        import threading
        thread = threading.Thread(
            target=self._extract_worker,
            args=(source, output_path, dit_path, vae_path, te_path, blocks, prompt, custom_blocks),
            daemon=True,
        )
        thread.start()

    def _extract_worker(self, source, output_path, dit_path, vae_path, te_path, blocks, prompt, custom_blocks=None):
        """Background worker for extraction."""
        try:
            import sys
            sys.path.insert(0, os.path.join(os.path.dirname(__file__), "src"))

            from fizgig.extraction.extractor import LoRAExtractor, ExtractionConfig

            timestep_presets = {
                "all": (0.0, 1.0),
                "early": (0.6, 1.0),
                "mid": (0.3, 0.7),
                "late": (0.0, 0.4),
            }

            rank = int(self.extract_rank_var.get())
            samples = int(self.extract_samples_var.get())
            timesteps = timestep_presets[self.extract_timesteps_var.get()]

            config = ExtractionConfig(
                source_lora_path=source,
                output_lora_path=output_path,
                target_rank=rank,
                timestep_range=timesteps,
                include_blocks=blocks,
                custom_blocks=custom_blocks,
                num_samples=samples,
                prompt=prompt,
                width=1024,
                height=1024,
                seed=42,
            )

            def progress(stage, current, total):
                def _update():
                    self.extract_progress_var.set(f"{stage}: {current+1}/{total}")
                self.master.after(0, _update)

            pipeline = None
            if samples == 0:
                # Pure weight SVD — no pipeline needed, no GPU models loaded
                self.master.after(0, lambda: self._extract_log(f"Pure weight SVD: blocks={blocks}, rank={rank}\n"))
                result = LoRAExtractor.extract_weight_only(config, progress_callback=progress)
            else:
                # Activation-weighted SVD — needs full pipeline for forward passes
                from fizgig.klein.inference import KleinInferencePipeline

                # Auto-detect model version and fp8 from filename
                dit_basename = os.path.basename(dit_path).lower()
                model_version = "klein-base-9b" if "base" in dit_basename else "klein-9b"
                is_fp8_model = "fp8" in dit_basename

                self.master.after(0, lambda: self._extract_log("Loading models...\n"))

                pipeline = KleinInferencePipeline()
                pipeline.load_models(
                    dit_path=dit_path,
                    vae_path=vae_path,
                    text_encoder_path=te_path,
                    model_version=model_version,
                    device="cuda",
                    fp8_scaled=not is_fp8_model,
                    fp8_text_encoder=True,
                    blocks_to_swap=self._get_inference_blocks_to_swap(),
                )

                self.master.after(0, lambda: self._extract_log(
                    f"Starting extraction: blocks={blocks}, rank={rank}, samples={samples}\n"))

                extractor = LoRAExtractor(pipeline)
                result = extractor.extract(config, progress_callback=progress)

            if pipeline is not None:
                pipeline.unload_models()

            # A valid-but-empty artifact is a failure, not a success: a Details preset on a
            # Style LoRA used to produce a ~340-byte tensorless file and "Extraction
            # complete! Layers extracted: 0".
            if result.num_layers_extracted == 0:
                try:
                    os.remove(result.output_path)
                except OSError:
                    pass
                raise RuntimeError(
                    f"Extraction produced 0 layers — the selected blocks ({blocks}) don't "
                    f"exist in this LoRA. Run it through the Profiler to see which blocks "
                    f"it actually trains, then pick a matching preset.")

            summary = f"\nExtraction complete!\n"
            summary += f"  Output: {result.output_path}\n"
            summary += f"  Layers extracted: {result.num_layers_extracted}\n"
            summary += f"  Target rank: {result.target_rank}\n"
            summary += f"  Total params: {result.total_params:,}\n"
            summary += f"  Time: {result.elapsed_seconds:.1f}s\n"

            self._extract_output_path = output_path

            def _update_ui():
                self._extract_log(summary)
                self.extract_progress_var.set("Done!")
                self.extract_run_btn.configure(state="normal")
                self.extract_open_btn.configure(state="normal")

            self.master.after(0, _update_ui)

        except Exception as e:
            import traceback
            error_msg = f"Extraction failed:\n{traceback.format_exc()}"
            def _show_error():
                self._extract_log(error_msg)
                self.extract_progress_var.set("Error")
                self.extract_run_btn.configure(state="normal")
            self.master.after(0, _show_error)

    # --- Krea 2 extract (weight-only SVD over all blocks; no pipeline / prompt / block map) ---

    def _on_extract_family_changed(self):
        fam = "krea2" if str(self.extract_family_var.get()) == "krea2" else "klein"
        self.last_used["extract_family"] = fam
        self._save_last_used_paths()
        self._apply_extract_family_ui(fam == "krea2")

    def _apply_extract_family_ui(self, is_krea2):
        """Krea 2 mode: pure weight SVD over all blocks. Hide the block-preset, custom-block,
        prompt and activation-probe (timesteps + forward passes) controls — only Target Rank
        plus Source/Output/Run remain. Klein mode restores everything."""
        # (widget, original padx) — restored verbatim so the klein branch is idempotent.
        probe_widgets = [
            (getattr(self, "_extract_timesteps_label", None), (0, 6)),
            (getattr(self, "_extract_timesteps_combo", None), (0, 20)),
            (getattr(self, "_extract_samples_label", None), (0, 6)),
            (getattr(self, "_extract_samples_combo", None), (0, 0)),
        ]
        if is_krea2:
            for c in (getattr(self, "_extract_preset_container", None),
                      getattr(self, "_extract_prompt_container", None)):
                if c is not None:
                    c.pack_forget()
            if getattr(self, "_extract_custom_frame", None) is not None:
                self._extract_custom_frame.pack_forget()
            for w, _ in probe_widgets:
                if w is not None:
                    w.pack_forget()
            # Force weight-only all-blocks regardless of stale Klein selections.
            self.extract_samples_var.set("0")
            self.extract_timesteps_var.set("all")
            self.extract_time_note_var.set(
                "⏱ Krea 2 is a 12.9B model — weight SVD runs over all 264 modules, several of "
                "them very large (e.g. 36864×6144). Expect roughly 5–10 minutes on a free GPU. "
                "If the GPU is busy (a training run, ComfyUI, another preview), each SVD falls back "
                "to the CPU and the whole run can take 60 min+ — free up VRAM first for the fast path.")
        else:
            anchor = getattr(self, "_extract_options_anchor", None)
            if getattr(self, "_extract_preset_container", None) is not None and anchor is not None:
                self._extract_preset_container.pack(fill=tk.X, padx=36, pady=(0, 16), before=anchor)
            run_anchor = getattr(self, "_extract_run_container", None)
            if getattr(self, "_extract_prompt_container", None) is not None and run_anchor is not None:
                self._extract_prompt_container.pack(fill=tk.X, padx=36, pady=(0, 16), before=run_anchor)
            # Re-pack probe widgets in their original order/padding after the rank combo.
            for w, padx in probe_widgets:
                if w is not None:
                    w.pack(side=tk.LEFT, padx=padx)
            # Custom-block frame visibility is owned by the preset combo; refresh it.
            if hasattr(self, "_on_extract_preset_changed"):
                self._on_extract_preset_changed()
            self.extract_time_note_var.set(
                "⏱ Fast SVD presets (weight-only) finish in well under a minute. Activation-weighted "
                "presets load the full pipeline and run probe forward passes — budget a few minutes. "
                "If the GPU is busy, SVD falls back to the CPU and runs much slower (a WARNING is logged).")

    def _run_extract_krea2(self):
        """Krea 2: pure weight SVD over all blocks — no pipeline, prompt, or block targeting."""
        source = self.extract_source_var.get()
        if not source or not os.path.exists(source):
            messagebox.showerror("Error", "Please select a valid source LoRA.")
            return

        output_name = self.extract_output_var.get().strip()
        if not output_name:
            messagebox.showerror("Error", "Please enter an output name.")
            return
        if not output_name.endswith(".safetensors"):
            output_name += ".safetensors"

        output_dir = self.prefs_vars["lora_output_dir"].get()
        os.makedirs(output_dir, exist_ok=True)
        output_path = os.path.join(output_dir, output_name)
        # Never silently overwrite (same rule as the Klein path).
        if os.path.exists(output_path):
            _stem, _ext = os.path.splitext(output_path)
            _n = 2
            while os.path.exists(f"{_stem}_{_n}{_ext}"):
                _n += 1
            output_path = f"{_stem}_{_n}{_ext}"

        self.extract_run_btn.configure(state="disabled")
        self.extract_open_btn.configure(state="disabled")
        self.extract_log.configure(state="normal")
        self.extract_log.delete(1.0, tk.END)
        self.extract_log.configure(state="disabled")
        self.extract_progress_var.set("Extracting...")

        import threading
        thread = threading.Thread(
            target=self._extract_worker_krea2,
            args=(source, output_path),
            daemon=True,
        )
        thread.start()

    def _extract_worker_krea2(self, source, output_path):
        """Background worker: weight-only SVD, model-agnostic (extract_weight_only with all blocks)."""
        try:
            import sys
            sys.path.insert(0, os.path.join(os.path.dirname(__file__), "src"))
            from fizgig.extraction.extractor import LoRAExtractor, ExtractionConfig

            rank = int(self.extract_rank_var.get())
            config = ExtractionConfig(
                source_lora_path=source,
                output_lora_path=output_path,
                target_rank=rank,
                timestep_range=(0.0, 1.0),
                include_blocks=["all"],
                custom_blocks=None,
                num_samples=0,
                prompt="",
                width=1024,
                height=1024,
                seed=42,
            )

            def progress(stage, current, total):
                self.master.after(0, lambda: self.extract_progress_var.set(f"{stage}: {current+1}/{total}"))

            self.master.after(0, lambda: self._extract_log(
                f"Krea 2 weight-only SVD (all blocks), rank={rank}\n"))
            result = LoRAExtractor.extract_weight_only(config, progress_callback=progress)

            # Empty artifact = failure, not success (same rule as the Klein worker).
            if result.num_layers_extracted == 0:
                try:
                    os.remove(result.output_path)
                except OSError:
                    pass
                raise RuntimeError("Extraction produced 0 layers — the source file contains "
                                   "no LoRA modules this extractor recognises.")

            summary = (f"\nExtraction complete!\n"
                       f"  Output: {result.output_path}\n"
                       f"  Layers extracted: {result.num_layers_extracted}\n"
                       f"  Target rank: {result.target_rank}\n"
                       f"  Total params: {result.total_params:,}\n"
                       f"  Time: {result.elapsed_seconds:.1f}s\n")
            self._extract_output_path = output_path

            def _update_ui():
                self._extract_log(summary)
                self.extract_progress_var.set("Done!")
                self.extract_run_btn.configure(state="normal")
                self.extract_open_btn.configure(state="normal")
            self.master.after(0, _update_ui)

        except Exception:
            import traceback
            error_msg = f"Extraction failed:\n{traceback.format_exc()}"
            def _show_error():
                self._extract_log(error_msg)
                self.extract_progress_var.set("Error")
                self.extract_run_btn.configure(state="normal")
            self.master.after(0, _show_error)

    # endregion

    # region Metadata Tab

    def create_metadata_tab(self):
        """Create the Metadata tab — view and edit the modelspec metadata on any .safetensors
        file: LoRAs, DiTs, text encoders, embeddings, whatever — including ones Fizgig didn't
        train, or trained before these fields existed."""
        scrollable_frame, _ = self.create_scrollable_frame(self.metadata_tab)

        outer = tk.Frame(scrollable_frame, bg=COLORS["bg_deep"])
        outer.pack(fill=tk.BOTH, expand=True)

        self._add_tab_banner(
            outer,
            "Metadata",
            "View and edit the SAI ModelSpec metadata embedded in a .safetensors file — title, "
            "author, description, trigger phrase, thumbnail, and anything else ComfyUI's model "
            "browser reads. Works on any .safetensors file — LoRA, DiT, text encoder, "
            "embedding — not just ones Fizgig trained.",
        )

        self._metadata_editor_path = None
        self._metadata_editor_thumbnail_uri = None  # current thumbnail data URI, or None
        self._metadata_editor_custom = {}  # every key outside the standard fields below
        self._metadata_thumb_photo = None  # keeps the PhotoImage alive; Tk drops it otherwise

        # --- Load ---
        load_card = self._start_section_card(
            outer, "File",
            "Pick any .safetensors file — LoRA, DiT, text encoder, embedding — its current "
            "metadata loads below.",
        )
        load_card.grid_columnconfigure(1, weight=1)
        ttk.Label(load_card, text="File:").grid(row=0, column=0, sticky=tk.W, padx=(0, 10), pady=4)
        self.metadata_file_var = tk.StringVar()
        ttk.Entry(load_card, textvariable=self.metadata_file_var, width=60).grid(
            row=0, column=1, sticky=tk.EW, pady=4)
        ttk.Button(load_card, text="Browse", command=self._browse_metadata_file).grid(
            row=0, column=2, sticky=tk.W, padx=(8, 0), pady=4)
        self._metadata_status_label = tk.Label(
            load_card, text="No file loaded.", font=(FONT_FAMILY, 9, "italic"),
            fg=COLORS["text_muted"], bg=COLORS["bg_surface"])
        self._metadata_status_label.grid(row=1, column=1, sticky=tk.W, pady=(2, 0))

        # --- Standard fields ---
        fields_card = self._start_section_card(
            outer, "Standard Fields",
            "The fields ComfyUI's model browser (and other spec-aware tools) render specially.",
        )
        fields_card.grid_columnconfigure(1, weight=1)

        def _field_row(label_text, row):
            ttk.Label(fields_card, text=label_text).grid(
                row=row, column=0, sticky=tk.NW, padx=(0, 10), pady=4)
            var = tk.StringVar()
            ttk.Entry(fields_card, textvariable=var, width=60).grid(
                row=row, column=1, sticky=tk.EW, pady=4)
            return var

        self.metadata_title_var = _field_row("Title:", 0)
        self.metadata_author_var = _field_row("Author:", 1)
        self.metadata_license_var = _field_row("License:", 2)
        self.metadata_tags_var = _field_row("Tags:", 3)
        self.metadata_trigger_var = _field_row("Trigger Phrase:", 4)
        self.metadata_usage_hint_var = _field_row("Usage Hint:", 5)

        ttk.Label(fields_card, text="Description:").grid(
            row=6, column=0, sticky=tk.NW, padx=(0, 10), pady=4)
        self.metadata_description_text = tk.Text(
            fields_card, width=60, height=5, wrap=tk.WORD,
            bg=COLORS["bg_surface"], fg=COLORS["text_primary"],
            insertbackground=COLORS["text_primary"], font=(FONT_FAMILY, 10),
            relief="flat", highlightthickness=1,
            highlightbackground=COLORS["border"], highlightcolor=COLORS["border_focus"],
        )
        self.metadata_description_text.grid(row=6, column=1, sticky=tk.EW, pady=4)

        # --- Thumbnail ---
        thumb_card = self._start_section_card(
            outer, "Thumbnail",
            "The image ComfyUI shows as card art. Fizgig auto-embeds the latest training sample "
            "when it trains a LoRA — replace or clear it here for any file.",
        )
        self._metadata_thumb_label = tk.Label(thumb_card, bg=COLORS["bg_surface"],
                                              text="(no thumbnail)", fg=COLORS["text_muted"])
        self._metadata_thumb_label.pack(anchor=tk.W, pady=(0, 8))
        thumb_btn_row = tk.Frame(thumb_card, bg=COLORS["bg_surface"])
        thumb_btn_row.pack(anchor=tk.W)
        ttk.Button(thumb_btn_row, text="Replace...",
                   command=self._browse_metadata_thumbnail).pack(side=tk.LEFT, padx=(0, 8))
        ttk.Button(thumb_btn_row, text="Clear",
                   command=self._clear_metadata_thumbnail).pack(side=tk.LEFT)

        # --- Custom fields ---
        custom_card = self._start_section_card(
            outer, "Custom Fields",
            "Like ID3 tags on an MP3 — the format isn't limited to a fixed list, and a reader "
            "just ignores whatever it doesn't recognize. Add anything you want: author_email, "
            "a colorspace profile note, whatever's useful to you. Not part of the SAI ModelSpec "
            "standard, so tools other than Fizgig won't render these specially, but they're "
            "stored in the file like any other metadata. Also shows any non-standard keys "
            "already in the file — nothing gets silently dropped on save.",
        )
        tree_frame = tk.Frame(custom_card, bg=COLORS["bg_surface"])
        tree_frame.pack(fill=tk.BOTH, expand=True)
        self.metadata_custom_tree = ttk.Treeview(
            tree_frame, columns=("key", "value"), show="headings", height=6)
        self.metadata_custom_tree.heading("key", text="Key")
        self.metadata_custom_tree.heading("value", text="Value")
        self.metadata_custom_tree.column("key", width=220, anchor=tk.W)
        self.metadata_custom_tree.column("value", width=420, anchor=tk.W)
        self.metadata_custom_tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        tree_scroll = ttk.Scrollbar(tree_frame, orient=tk.VERTICAL,
                                    command=self.metadata_custom_tree.yview)
        tree_scroll.pack(side=tk.LEFT, fill=tk.Y)
        self.metadata_custom_tree.configure(yscrollcommand=tree_scroll.set)

        custom_btn_row = tk.Frame(custom_card, bg=COLORS["bg_surface"])
        custom_btn_row.pack(anchor=tk.W, pady=(8, 0))
        ttk.Button(custom_btn_row, text="Add field...",
                   command=self._add_metadata_custom_field).pack(side=tk.LEFT, padx=(0, 8))
        ttk.Button(custom_btn_row, text="Remove selected",
                   command=self._remove_metadata_custom_field).pack(side=tk.LEFT)

        # --- Save ---
        save_row = tk.Frame(outer, bg=COLORS["bg_deep"])
        save_row.pack(fill=tk.X, padx=36, pady=(0, 20))
        ttk.Button(save_row, text="Save",
                   command=lambda: self._save_metadata_file(save_as=False)).pack(
            side=tk.LEFT, padx=(0, 8))
        ttk.Button(save_row, text="Save As...",
                   command=lambda: self._save_metadata_file(save_as=True)).pack(side=tk.LEFT)
        self._metadata_save_status = tk.Label(
            save_row, text="", font=(FONT_FAMILY, 9, "italic"),
            fg=COLORS["text_muted"], bg=COLORS["bg_deep"])
        self._metadata_save_status.pack(side=tk.LEFT, padx=(16, 0))

    def _browse_metadata_file(self):
        filepath = filedialog.askopenfilename(
            title="Select a .safetensors file",
            filetypes=[("SafeTensors", "*.safetensors"), ("All files", "*.*")],
            initialdir=self._lora_initialdir(),
        )
        if filepath:
            self.metadata_file_var.set(filepath)
            self._load_metadata_file(filepath)

    def _load_metadata_file(self, path):
        from fizgig.training.metadata import load_metadata_from_safetensors
        try:
            meta = load_metadata_from_safetensors(path)
        except Exception as e:
            messagebox.showerror("Error", f"Could not read metadata:\n{e}")
            return

        self._metadata_editor_path = path
        standard = {
            "modelspec.title": self.metadata_title_var,
            "modelspec.author": self.metadata_author_var,
            "modelspec.license": self.metadata_license_var,
            "modelspec.tags": self.metadata_tags_var,
            "modelspec.trigger_phrase": self.metadata_trigger_var,
            "modelspec.usage_hint": self.metadata_usage_hint_var,
        }
        for key, var in standard.items():
            var.set(meta.get(key, "") or "")

        self.metadata_description_text.delete("1.0", tk.END)
        self.metadata_description_text.insert("1.0", meta.get("modelspec.description", "") or "")

        self._metadata_editor_thumbnail_uri = meta.get("modelspec.thumbnail")
        self._show_metadata_thumbnail_preview(self._metadata_editor_thumbnail_uri)

        skip_keys = set(standard.keys()) | {"modelspec.description", "modelspec.thumbnail"}
        self._metadata_editor_custom = {k: v for k, v in meta.items() if k not in skip_keys}
        self._refresh_metadata_custom_tree()

        n = len(meta)
        self._metadata_status_label.config(
            text=f"Loaded — {n} metadata key{'s' if n != 1 else ''} found.",
            fg=COLORS["text_secondary"])
        self._metadata_save_status.config(text="")

    def _show_metadata_thumbnail_preview(self, data_uri):
        if not data_uri or not str(data_uri).startswith("data:image"):
            self._metadata_thumb_label.config(image="", text="(no thumbnail)")
            self._metadata_thumb_photo = None
            return
        try:
            import base64
            from io import BytesIO
            b64 = data_uri.split(",", 1)[1]
            img = Image.open(BytesIO(base64.b64decode(b64)))
            img.thumbnail((256, 256))
            photo = ImageTk.PhotoImage(img)
            self._metadata_thumb_photo = photo  # reference kept alive deliberately
            self._metadata_thumb_label.config(image=photo, text="")
        except Exception:
            self._metadata_thumb_label.config(image="", text="(couldn't decode thumbnail)")
            self._metadata_thumb_photo = None

    def _browse_metadata_thumbnail(self):
        filepath = filedialog.askopenfilename(
            title="Select a thumbnail image",
            filetypes=[("Images", "*.png *.jpg *.jpeg *.webp"), ("All files", "*.*")],
        )
        if not filepath:
            return
        from fizgig.training.metadata import thumbnail_data_uri
        uri = thumbnail_data_uri(filepath)
        if not uri:
            messagebox.showerror("Error", "Could not read that image.")
            return
        self._metadata_editor_thumbnail_uri = uri
        self._show_metadata_thumbnail_preview(uri)

    def _clear_metadata_thumbnail(self):
        self._metadata_editor_thumbnail_uri = None
        self._show_metadata_thumbnail_preview(None)

    def _refresh_metadata_custom_tree(self):
        self.metadata_custom_tree.delete(*self.metadata_custom_tree.get_children())
        for k, v in sorted(self._metadata_editor_custom.items()):
            display_v = v if len(str(v)) <= 120 else str(v)[:117] + "..."
            self.metadata_custom_tree.insert("", tk.END, iid=k, values=(k, display_v))

    def _add_metadata_custom_field(self):
        dlg = tk.Toplevel(self.master)
        dlg.title("Add custom field")
        dlg.configure(bg=BG_COLOR)
        dlg.transient(self.master)
        tk.Label(dlg, text="Key:", bg=BG_COLOR, fg=COLORS["text_secondary"]).grid(
            row=0, column=0, sticky=tk.W, padx=10, pady=(10, 2))
        key_entry = ttk.Entry(dlg, width=40)
        key_entry.grid(row=0, column=1, padx=10, pady=(10, 2))
        tk.Label(dlg, text="Value:", bg=BG_COLOR, fg=COLORS["text_secondary"]).grid(
            row=1, column=0, sticky=tk.W, padx=10, pady=2)
        val_entry = ttk.Entry(dlg, width=40)
        val_entry.grid(row=1, column=1, padx=10, pady=2)

        def ok():
            k = key_entry.get().strip()
            v = val_entry.get().strip()
            if k:
                self._metadata_editor_custom[k] = v
                self._refresh_metadata_custom_tree()
            dlg.destroy()

        btn_row = tk.Frame(dlg, bg=BG_COLOR)
        btn_row.grid(row=2, column=0, columnspan=2, pady=10)
        ttk.Button(btn_row, text="Cancel", command=dlg.destroy).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_row, text="Add", command=ok).pack(side=tk.LEFT, padx=5)
        key_entry.bind("<Return>", lambda e: ok())
        key_entry.focus_set()
        dlg.grab_set()

    def _remove_metadata_custom_field(self):
        for k in self.metadata_custom_tree.selection():
            self._metadata_editor_custom.pop(k, None)
        self._refresh_metadata_custom_tree()

    def _save_metadata_file(self, save_as=False):
        if not self._metadata_editor_path:
            messagebox.showinfo("No file loaded", "Load a .safetensors file first.")
            return

        dest = self._metadata_editor_path
        if save_as:
            dest = filedialog.asksaveasfilename(
                title="Save file as",
                defaultextension=".safetensors",
                filetypes=[("SafeTensors", "*.safetensors")],
                initialfile=os.path.basename(self._metadata_editor_path),
            )
            if not dest:
                return
        elif not messagebox.askyesno(
                "Overwrite?",
                f"Save metadata changes to:\n{dest}\n\nThis overwrites the file in place."):
            return

        try:
            from safetensors.torch import load_file, save_file
            # .clone() forces a real copy out of the mmap'd view load_file returns. Without
            # this, saving back onto the SAME path fails on Windows with "the requested
            # operation cannot be performed on a file with a user-mapped section open"
            # (error 1224) — the mapping from this exact load is still active, and Windows
            # (unlike Linux) refuses to overwrite a file while it's mapped. Cloning breaks
            # that dependency before we ever try to write.
            tensors = {k: v.clone() for k, v in load_file(self._metadata_editor_path).items()}
        except Exception as e:
            messagebox.showerror("Error", f"Could not read the file's tensors:\n{e}")
            return

        new_meta = dict(self._metadata_editor_custom)
        field_map = {
            "modelspec.title": self.metadata_title_var.get().strip(),
            "modelspec.author": self.metadata_author_var.get().strip(),
            "modelspec.license": self.metadata_license_var.get().strip(),
            "modelspec.tags": self.metadata_tags_var.get().strip(),
            "modelspec.trigger_phrase": self.metadata_trigger_var.get().strip(),
            "modelspec.usage_hint": self.metadata_usage_hint_var.get().strip(),
            "modelspec.description": self.metadata_description_text.get("1.0", "end-1c").strip(),
        }
        for k, v in field_map.items():
            if v:
                new_meta[k] = v
        if self._metadata_editor_thumbnail_uri:
            new_meta["modelspec.thumbnail"] = self._metadata_editor_thumbnail_uri

        # A metadata-only edit still goes through a full resave, which isn't guaranteed to be
        # byte-identical to the original — so hashes computed over the old bytes can no longer
        # be trusted. Same move bake.py already makes whenever it changes a file's contents.
        for stale in ("sshs_model_hash", "sshs_legacy_hash", "modelspec.hash_sha256"):
            new_meta.pop(stale, None)

        # Write to a temp file and swap it in atomically, so a failed/interrupted save can
        # never leave the original file half-written.
        tmp_dest = dest + ".tmp"
        try:
            save_file(tensors, tmp_dest, metadata=new_meta)
            os.replace(tmp_dest, dest)
        except Exception as e:
            try:
                if os.path.exists(tmp_dest):
                    os.remove(tmp_dest)
            except OSError:
                pass
            messagebox.showerror("Error", f"Could not save:\n{e}")
            return

        self._metadata_save_status.config(text=f"Saved {os.path.basename(dest)}",
                                          fg=COLORS["text_secondary"])
        if save_as:
            self.metadata_file_var.set(dest)
            self._metadata_editor_path = dest

    # endregion

    # region Preferences Tab

